public class EggDrop {
    public int superEggDrop(int k, int n) {
        // dp[m][k] = max floors testable with m moves and k eggs
        int[][] dp = new int[n+1][k+1];
        int m = 0;
        while (dp[m][k] < n) {
            m++;
            for (int j = 1; j <= k; j++)
                dp[m][j] = dp[m-1][j-1] + dp[m-1][j] + 1;
        }
        return m;
    }
    public static void main(String[] args) {
        System.out.println(new EggDrop().superEggDrop(2, 100)); // 14
        System.out.println(new EggDrop().superEggDrop(3, 14));  // 4
    }
}

